create or replace view gov_repo.v_ict_dora_reporting_status as select i.organisation_id,i.incident_id,i.incident_code,i.title,i.severity,i.is_major_incident,i.reporting_phase,i.competent_authority,i.nca_case_ref,i.initial_notification_deadline,i.initial_notification_sent_at,i.initial_notification_ref,(i.initial_notification_sent_at is null and i.initial_notification_deadline is not null and i.initial_notification_deadline<now()) as initial_overdue,i.intermediate_report_deadline,i.intermediate_report_sent_at,i.intermediate_report_ref,(i.intermediate_report_sent_at is null and i.intermediate_report_deadline is not null and i.intermediate_report_deadline<now()) as intermediate_overdue,i.final_report_deadline,i.final_report_sent_at,i.final_report_ref,(i.final_report_sent_at is null and i.final_report_deadline is not null and i.final_report_deadline<now()) as final_overdue,((i.initial_notification_sent_at is not null and i.initial_notification_sent_at<=i.initial_notification_deadline) and(i.intermediate_report_sent_at is not null and i.intermediate_report_sent_at<=i.intermediate_report_deadline) and(i.final_report_sent_at is not null and i.final_report_sent_at<=i.final_report_deadline)) as fully_compliant,(select count(*) from gov_repo.ict_incident_notifications n where n.incident_id=i.incident_id and n.is_breached=true) as breach_count,i.voluntary_notif_sent_at,i.occurred_at,i.reported_at from gov_repo.ict_incidents i where i.is_major_incident=true order by case when i.initial_notification_sent_at is null and i.initial_notification_deadline<now() then 1 when i.initial_notification_deadline is not null and i.initial_notification_deadline>now() and extract(epoch from(i.initial_notification_deadline-now()))<3600 then 2 else 3 end,i.initial_notification_deadline asc;
create or replace view gov_repo.v_ict_ai_impact_lens as select i.organisation_id,i.incident_id,i.incident_code,i.title,i.severity,i.incident_category,i.status,i.recovery_status,i.involves_ai_system,s.system_id,s.system_code,s.name as ai_system_name,s.risk_class as ai_system_risk_class,s.lifecycle as ai_system_lifecycle,i.ai_act_reporting_required,i.ai_serious_incident_id,i.ai_root_cause_type,i.control_failures,i.impacted_system_ids,i.impacted_agent_ids,(select count(*) from gov_repo.ict_incident_affected_services svc where svc.incident_id=i.incident_id and svc.ai_system_id is not null) as ai_services_affected,i.financial_impact_eur,i.rto_target_minutes,i.rto_actual_minutes,i.rto_breach,i.occurred_at,i.detected_at,i.recovery_completed_at,u.full_name as ai_system_owner from gov_repo.ict_incidents i left join gov_repo.ai_systems s on s.system_id=i.primary_ai_system_id left join gov_repo.governance_users u on u.user_id=s.owner_user_id where i.involves_ai_system=true order by case i.severity when 'critical' then 1 when 'high' then 2 else 3 end,i.occurred_at desc nulls last;
create or replace view gov_repo.v_ict_recovery_tracker as select i.organisation_id,i.incident_id,i.incident_code,i.title,i.severity,i.status,i.recovery_status,i.occurred_at,i.contained_at,i.eradication_started_at,i.eradication_completed_at,i.recovery_started_at,i.recovery_completed_at,i.monitoring_started_at,i.monitoring_ends_at,i.rto_target_minutes,i.rto_actual_minutes,i.rto_breach,i.rpo_target_minutes,i.data_loss_minutes,i.rpo_breach,i.workaround_applied,i.permanent_fix_applied,i.permanent_fix_date,i.pir_conducted,i.pir_date,i.lessons_learned is not null as lessons_learned_documented,case i.recovery_status when 'not_started' then 0 when 'containment_active' then 15 when 'eradication_active' then 35 when 'recovery_active' then 55 when 'restored_partial' then 70 when 'restored_full' then 85 when 'monitoring_period' then 90 when 'lessons_learned_pending' then 95 when 'closed' then 100 else 0 end as recovery_progress_pct,i.involves_third_party,p.name as provider_name,i.provider_sla_breach,u.full_name as incident_commander from gov_repo.ict_incidents i left join gov_repo.third_party_providers p on p.provider_id=i.primary_provider_id left join gov_repo.governance_users u on u.user_id=i.incident_commander_id where i.status not in ('closed') order by case i.recovery_status when 'not_started' then 1 when 'containment_active' then 2 when 'eradication_active' then 3 when 'recovery_active' then 4 when 'restored_partial' then 5 else 6 end,case i.severity when 'critical' then 1 when 'high' then 2 else 3 end;
create or replace view gov_repo.v_ict_third_party_incident_concentration as select p.organisation_id,p.provider_id,p.provider_code,p.name as provider_name,p.service_type,p.dora_criticality,p.status as provider_status,p.contract_expires_at,p.exit_plan_documented,p.concentration_risk_score,count(i.incident_id) as total_incidents,count(i.incident_id) filter(where i.is_major_incident) as major_incidents,count(i.incident_id) filter(where i.severity='critical') as critical_incidents,count(i.incident_id) filter(where i.status not in ('resolved','closed')) as open_incidents,max(i.occurred_at) as last_incident_at,coalesce(sum(i.financial_impact_eur),0) as total_financial_impact_eur,count(i.incident_id) filter(where i.rto_breach=true) as rto_breaches,(select count(distinct rl.agent_id) from gov_repo.agent_resource_links rl where rl.provider_id=p.provider_id and rl.is_active=true) as linked_agents,(select count(distinct a.ai_system_id) from gov_repo.agent_resource_links rl join gov_repo.agents a on a.agent_id=rl.agent_id where rl.provider_id=p.provider_id and rl.is_active=true and a.ai_system_id is not null) as linked_ai_systems from gov_repo.third_party_providers p left join gov_repo.ict_incidents i on i.primary_provider_id=p.provider_id group by p.organisation_id,p.provider_id,p.provider_code,p.name,p.service_type,p.dora_criticality,p.status,p.contract_expires_at,p.exit_plan_documented,p.concentration_risk_score order by major_incidents desc,total_incidents desc,p.dora_criticality;;
